  const items = [];

  $('.elementor-price-list').each((_, ul) => {
    const $ul = $(ul);
    // Determine section heading
    let sectionName = null;
    const $section = $ul.closest('section');
    if ($section.length) {
      const $heading = $section.find('.elementor-heading-title').first();
      if ($heading.length) {
        sectionName = cleanText($heading.text());
      }
    }

    $ul.find('li.elementor-price-list-item').each((_, li) => {
      const $li = $(li);
      const $header = $li.find('.elementor-price-list-header');
      if (!$header.length) return;

      const $titleEl = $header.find('.elementor-price-list-title');
      const $priceEl = $header.find('.elementor-price-list-price');
      const nameRaw = $titleEl.text();
      const priceRaw = $priceEl.text();

      const name = cleanText(nameRaw);
      if (!name) return;

      const price = parsePrice(priceRaw);

      const $descEl = $li.find('.elementor-price-list-description');
      const description = $descEl.length ? cleanText($descEl.text()) : null;

      items.push({ section: sectionName, name, description: description, price });
    });
  });

  // Remove exact duplicates (e.g., mobile/desktop copies)
  const seen = new Set();
  return items.filter(item => {
    const key = JSON.stringify(item);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
